def solve(facts):
    def decimal(s):
        return Fraction(str(s))
    subtotal = 0
    for line in facts["lines"]:
        amount = Fraction(line["qty"] * line["unit_cents"]) * (1 - decimal(line["discount_percent"]) / 100)
        subtotal += (2 * amount.numerator + amount.denominator) // (2 * amount.denominator)
    tax = Fraction(subtotal) * decimal(facts["tax_percent"]) / 100
    tax_cents = (2 * tax.numerator + tax.denominator) // (2 * tax.denominator)
    return {"subtotal_cents": subtotal, "tax_cents": tax_cents, "total_cents": subtotal + tax_cents + facts["shipping"]}

def check(answer, facts):
    def decimal(s):
        return Fraction(str(s))
    computed_subtotal = 0
    for line in facts["lines"]:
        numerator = line["qty"] * line["unit_cents"] * (100 * decimal(line["discount_percent"]).denominator - decimal(line["discount_percent"]).numerator)
        denominator = 100 * decimal(line["discount_percent"]).denominator
        computed_subtotal += (2 * numerator + denominator) // (2 * denominator)
    tax_fraction = Fraction(computed_subtotal) * decimal(facts["tax_percent"]) / 100
    computed_tax = (2 * tax_fraction.numerator + tax_fraction.denominator) // (2 * tax_fraction.denominator)
    return answer == {"subtotal_cents": computed_subtotal, "tax_cents": computed_tax, "total_cents": computed_subtotal + computed_tax + facts["shipping"]}"}

